export const WORD_SET = new Set(
  RAW_WORDS.toLowerCase()
    .split(/\s+/)
    .map((w) => w.trim())
    .filter((w) => w.length >= 2 && /^[a-z]+$/.test(w))
);

// Also add all single-word draw words to WORD_SET
for (const entry of DRAW_WORDS) {
  for (const part of entry.word.toLowerCase().split(/\s+/)) {
    if (part.length >= 2 && /^[a-z]+$/.test(part)) {
      WORD_SET.add(part);
    }
  }
}

// Common Indonesian prefixes/suffixes so valid inflected Indonesian words (e.g., "bermain", "makanan", "kucingnya", "menulis") are accepted!
const ID_PREFIXES = ['meng', 'meny', 'mem', 'men', 'me', 'peng', 'peny', 'pem', 'pen', 'pe', 'ber', 'ter', 'per', 'di', 'ke', 'se'];
const ID_SUFFIXES = ['kannya', 'inya', 'nya', 'kan', 'lah', 'kah', 'tah', 'pun', 'an', 'in', 'ku', 'mu', 'i'];
const EN_SUFFIXES = ['ings', 'ing', 'ies', 'ied', 'ers', 'est', 'ed', 'er', 'es', 'ly', 's'];

export function isValidWord(raw) {
  const w = raw.toLowerCase().trim();
  if (!/^[a-z]{2,28}$/.test(w)) return false;
  if (WORD_SET.has(w)) return true;

  // Check English inflections
  for (const suf of EN_SUFFIXES) {
    if (w.endsWith(suf) && w.length - suf.length >= 3) {
      const stem = w.slice(0, -suf.length);
      if (WORD_SET.has(stem) || WORD_SET.has(stem + 'e') || WORD_SET.has(stem + 'y')) {
        return true;
      }
    }
  }

  // Check Indonesian prefix/suffix combinations
  const stems = [w];
  for (const suf of ID_SUFFIXES) {
    if (w.endsWith(suf) && w.length - suf.length >= 3) {
      stems.push(w.slice(0, -suf.length));
    }
  }
  for (const st of stems) {
    if (WORD_SET.has(st)) return true;
    for (const pre of ID_PREFIXES) {
      if (st.startsWith(pre) && st.length - pre.length >= 3) {
        const root = st.slice(pre.length);
        if (WORD_SET.has(root)) return true;
        // Nasal assimilation (k->ng, p->m, t->n, s->ny)
        if (pre === 'meng' || pre === 'peng') {
          if (WORD_SET.has('k' + root)) return true;
        }
        if (pre === 'mem' || pre === 'pem') {
          if (WORD_SET.has('p' + root)) return true;
        }
        if (pre === 'men' || pre === 'pen') {
          if (WORD_SET.has('t' + root)) return true;
        }
        if (pre === 'meny' || pre === 'peny') {
          if (WORD_SET.has('s' + root)) return true;
        }
      }
    }
  }

  // Reduplication like "kupu-kupu" -> "kupukupu" or "jalanjalan"
  if (w.length >= 6 && w.length % 2 === 0) {
    const half = w.slice(0, w.length / 2);
    if (half === w.slice(w.length / 2) && WORD_SET.has(half)) return true;
  }

  return false;
}

export function findWordsForSyllable(syllable, usedSet, maxCount = 8) {
  const syl = syllable.toLowerCase();
  const matches = [];
  for (const w of WORD_SET) {
    if (w.length >= 4 && w.length <= 10 && w.includes(syl) && !usedSet.has(w)) {
      matches.push(w);
      if (matches.length >= maxCount * 5) break;
    }
  }
  return matches;
}

export function findWordsStartingWith(prefix, usedSet, maxCount = 12) {
  const pre = prefix.toLowerCase();
  const matches = [];
  for (const w of WORD_SET) {
    if (w.length >= Math.max(3, pre.length + 1) && w.length <= 12 && w.startsWith(pre) && !usedSet.has(w)) {
      matches.push(w);
      if (matches.length >= maxCount * 4) break;
    }
  }
  return matches;
}

export function extractNextSyllable(word, usedSet) {
  const clean = word.toLowerCase().replace(/[^a-z]/g, '');
  // Try last 3 letters first (e.g. "dalam" -> "lam", "makan" -> "kan") if enough continuation words exist
  if (clean.length >= 4) {
    const tail3 = clean.slice(-3);
    if (findWordsStartingWith(tail3, usedSet, 3).length >= 3) {
      return tail3.toUpperCase();
    }
  }
  // Fallback to last 2 letters (e.g. "lampu" -> "pu", "bola" -> "la")
  if (clean.length >= 3) {
    const tail2 = clean.slice(-2);
    if (findWordsStartingWith(tail2, usedSet, 2).length >= 2) {
      return tail2.toUpperCase();
    }
  }
  // Last letter fallback so players never hit an impossible dead end
  const tail1 = clean.slice(-1);
  if (tail1 && findWordsStartingWith(tail1, usedSet, 2).length >= 2) {
    return tail1.toUpperCase();
  }
  return WORD_BOMB_SYLLABLES[Math.floor(Math.random() * WORD_BOMB_SYLLABLES.length)];
}

export function levenshtein(a, b) {
  if (a === b) return 0;
  if (!a.length) return b.length;
  if (!b.length) return a.length;
  const v0 = new Array(b.length + 1);
  const v1 = new Array(b.length + 1);
  for (let i = 0; i <= b.length; i++) v0[i] = i;
  for (let i = 0; i < a.length; i++) {
    v1[0] = i + 1;
    for (let j = 0; j < b.length; j++) {
      const cost = a[i] === b[j] ? 0 : 1;
      v1[j + 1] = Math.min(v1[j] + 1, v0[j + 1] + 1, v0[j] + cost);
    }
    for (let j = 0; j <= b.length; j++) v0[j] = v1[j];
  }
  return v0[b.length];
}
